from .ttitrace import TtiTrace

import re
import time
import pkg_resources
import logging
import six


class Fsm4TddTtiTrace(TtiTrace):
    KEY_PARAMS = {'port': 'P',
                  'ip_addr': 'i',
                  'filesize': 'm',
                  'prefix': 'o',
                  'task': 't',
                  'duration': 'u'}

    def __init__(self, host_ip, ssh_username, ssh_password, ssh_prompt, ssh_port, stream_path,
                 tracer_path, ip_addr, timeout, log_path, sw_version, cells_sw_type):
        super(Fsm4TddTtiTrace, self).__init__(host_ip, ssh_username, ssh_password, ssh_prompt,
                                              ssh_port, stream_path, tracer_path, ip_addr,
                                              timeout, log_path, sw_version, cells_sw_type)
        self._ip_addr = ip_addr
        self._started = False

    def start_tti_stream(self, core, param):
        """Start ttiStream with provided params
        """
        if self._started:
            raise Exception('Tti Stream already started.')
        if 'ip_addr' not in param:
            param['ip_addr'] = self._ip_addr
        string_params = self._convert_to_params(param)
        cmd = 'cd {};sudo {} -p toor4nsn@oZPS0POrRieRtu -c {} {}'.format(self._log_path, self._stream_path, core, string_params)
        self._executor.write_to_shell("{}\n".format(cmd.strip()))
        self.output = self._executor.read_until_regexp('open a new trace file')
        if "ERR" in self.output:
            self._executor.write_to_shell('\n')
            self._started = False
            raise Exception(self.output)
        else:
            self._started = True

    def stop_tti_stream(self, lrc=None):
        """Stop running ttiStream
        """
        if not self._started:
            raise Exception('There is no started ttiStream')
        self._executor.write_to_shell('\n')
        self._started = False
        out = self._get_created_dat_file()
        self._log_files.extend(out)
        return out

    def stop_tti_stream_and_convert_to_text(self, nb, ext='txt', lrc=None):
        """Stop running ttiStream and convert dat files to txt
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension
        :return list:                   List of successfully converted txt file
        """
        dat_files = self.stop_tti_stream()
        return list(filter(None, [self.convert_dat_to_text(source=file, destination=None, nb=nb, ext=ext) for file in dat_files]))

    def convert_dat_to_text(self, source, destination, nb, ext='txt'):
        """Converts source dat file to readable text file
        :param source string:           Input dat file name
        :param destination string:      Output txt file name
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension, ignored when destination is given
        :return string:                 Output txt file or empty string if txt file not created
        """
        destination = destination or "{}.{}".format(source, ext)
        cmd = 'cd {}; {} {} {}'.format(self._log_path, self._tracer_path, source, destination)
        out = self._executor.run(cmd.strip())
        if re.search('parse complete.', out):
            output_file = self._attach_log_path_if_not_absolute(destination)
            self._log_files.append(output_file)
            return output_file
        return ''

    def get_tti_dl_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:                TTI DL Node
        """
        return self._get_node(lcr, table='MACDLTTI')

    def get_tti_ul_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:         TTI UL Node
        """
        return self._get_node(lcr, table='MACULTTI')

    def _get_default_stream_path(self):
        stream_name = 'onlineTtiStream_64'
        stream_path = self._find_tracer_path(stream_name, '/opt/TtiTracer')
        return stream_path

    def _get_default_tracer_path(self):
        tracer_name = 'DevC_tti_trace_parser_64'
        tracer_path = self._find_tracer_path(tracer_name, '/opt/TtiTracer')
        return tracer_path

    def _find_tracer_path(self, name, path):
        try:
            return self._executor.run('find {} -name {}'.format(path, name)).split()[0]
        except Exception:
            raise Exception('Default Ttitracer not found.')

    def _convert_to_params(self, parameters):
        ret = ''
        for key, value in six.iteritems(parameters):
            if 'task' == key or 'duration' == key:
                ret = ret
            elif 'debug_level' == key:
                ret = '{} -{}'.format(ret, 'D' * value)
            else:
                ret = '{} -{} {}'.format(ret, self.KEY_PARAMS[key], value)
        return ret.strip()

    def _get_created_dat_file(self):
        out = self._executor.read_shell()
        return self._extract_dat_files_from_output('{}{}'.format(self.output, out))

    def _extract_dat_files_from_output(self, out):
        output_regex = r'open a new trace file.*/(\w+\.dat).*'
        lines = out.splitlines()
        p = re.compile(output_regex)
        dat_files = [p.match(line).group(1) for line in lines if p.match(line)]
        if not len(dat_files):
            raise Exception('No Dat File was created.')
        else:
            return self._attach_log_path_to_output(dat_files)

    def _get_node(self, lcr, table):
        cell_info_table = self._get_cell_info_table()
        lcr = lcr or self._get_first_local_cell_resource_id(cell_info_table)
        column = self._get_table_column(cell_info_table, table)
        return self._extract_node(cell_info_table, lcr, column)

    def _get_cell_info_table(self):
        tool_path = '{}/{}'.format(pkg_resources.resource_filename('ta_ttitrace', "resources"), 'getcellmapping')
        self._executor.run('sudo chmod u+x {}'.format(tool_path))
        cmd = 'sudo {} {} 15007'.format(tool_path, self._ip_addr)
        out = self._executor.run(cmd)
        cell_info_table = self._extract_table_from_output(out)
        return cell_info_table

    def _extract_table_from_output(self, out):
        try:
            return re.search(r'(lcr lnCel.*\n[\w\s.-]+)', out, re.MULTILINE).group(1)
        except Exception:
            raise Exception('Table not found.')

    def _get_first_local_cell_resource_id(self, cell_info_table):
        cells = cell_info_table.splitlines()
        return cells[1].split()[0]

    def _get_table_column(self, cell_info_table, table):
        cells = cell_info_table.splitlines()
        tables = cells[0].split()
        for index in range(0, len(tables)):
            if table == tables[index]:
                return index
        raise Exception("{} did not match any table name".format(table))

    def _extract_node(self, cell_info_table, lcr, node):
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[0] == lcr:
                return cell.split()[node][:10] if len(cell.split()[node]) >= 10 else cell.split()[node][:6]
        raise Exception('{} did not match any local cell resource'.format(lcr))


class Fsm4FddTtiTrace(TtiTrace):

    def __init__(self, host_ip, ssh_username, ssh_password, ssh_prompt, ssh_port, stream_path,
                 tracer_path, ip_addr, timeout, log_path, sw_version, cells_sw_type):
        self._log = logging.getLogger(__name__)
        super(Fsm4FddTtiTrace, self).__init__(host_ip, ssh_username, ssh_password, ssh_prompt,
                                              ssh_port, stream_path, tracer_path, ip_addr,
                                              timeout, log_path, sw_version, cells_sw_type)
        self._ip_addr = ip_addr
        self._started = False
        self._cell_id = []
        self._is_server_model = True

    def start_tti_stream(self, core, param):
        """Start ttiStream with provided params
        """
        if self._started:
            raise Exception('Tti Stream already started.')
        if len(core.split(',')) < 2:
            raise Exception("Both DL and UL core are needed.")

        param = self._set_default_value(param)
        self._prefix = param['prefix']
        self._port = param['port']

        server_cmd = 'cd {};sudo {} -H r4 -s 1 -c defaultTraces=0 -c tracing_disabled=1 -p {} -M 0' \
            .format(self._log_path, self._stream_path['server'], param['port'])
        self._executor.write_to_shell('{}\n'.format(server_cmd))
        self._executor.read_until('node settings:')
        time.sleep(6)

        core_id_pre_cell = self._separate_core_id(core)
        for core_id in core_id_pre_cell:
            lncell = self._get_lncell_by_core(core_id)
            self._cell_id.append(lncell)

            client_cmd1 = 'sudo {} -m CLIAATRACE_MSG_ID_REGISTER_CELL_ID_PACKET_SCHEDULER_MAPPING -c "{} {}"'\
                          .format(self._stream_path['client'], lncell, core_id.replace(',', ' '))
            self._execute_tti_stream_cmd(client_cmd1, 'received msg ID:')

            client_cmd2 = 'sudo {} -m CLIAATRACE_MSG_ID_LTE2114_Q_B_TTI_TRACE_START -c "{} {}"'\
                          .format(self._stream_path['client'], param['prefix'], lncell)
            self._execute_tti_stream_cmd(client_cmd2, 'START LTE211-Q-b streaming  OK')

        self._started = True

    def stop_tti_stream(self, lrc=None):
        """Stop running ttiStream
        """
        if not self._started:
            raise Exception('There is no started ttiStream')
        for cell in self._cell_id:
            stop_cmd = 'sudo {} -m CLIAATRACE_MSG_ID_LTE2114_Q_B_TTI_TRACE_STOP -c "{}"'\
                .format(self._stream_path['client'], cell)
            self._execute_tti_stream_cmd(stop_cmd)
        self._started = False
        out = self._get_created_dat_file()
        self._log_files.extend(out)
        self._cell_id = []
        return out

    def stop_tti_stream_and_convert_to_text(self, nb, ext='txt', lrc=None):
        """Stop running ttiStream and convert dat files to txt
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension
        :return list:                   List of successfully converted txt file
        """
        dat_files = self.stop_tti_stream()
        return list(filter(None, [self.convert_dat_to_text(source=file, destination=None, nb=nb, ext=ext) for file in dat_files]))

    def convert_dat_to_text(self, source, destination, nb, ext='txt'):
        """Converts source dat file to readable text file
        :param source string:           Input dat file name
        :param destination string:      Output txt file name
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension, ignored when destination is given
        :return string:                 Output txt file or empty string if txt file not created
        """
        destination = destination or "{}.{}".format(source, ext)
        cmd = 'cd {};sudo {} --decode {} --output {} {}'.format(self._log_path, self._tracer_path, source, destination,
                                                                '-nb' if nb else '')
        out = self._executor.run(cmd.strip())
        output = self._validate_ouput_file_created(out)
        if output:
            self._log_files.append(output)
        return output

    def get_tti_dl_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:                TTI DL Node
        """
        return self._get_node(lcr, table='MACDLTTI')

    def get_tti_ul_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:         TTI UL Node
        """
        return self._get_node(lcr, table='MACULTTI')

    def _get_lncell_by_core(self, core):
        input_core = core.split(',')
        input_core.sort()
        cell_info_table = self._get_cell_info_table()
        column = self._get_table_column(cell_info_table, table='MACDLTTI')
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[1].isdigit() and cell.split()[column] in input_core and cell.split()[1] not in self._cell_id:
                return cell.split()[1]
        else:
            raise Exception("The core is not for any cell.")

    def _set_default_value(self, param):
        param.setdefault('ip_addr', self._ip_addr)
        param.setdefault('port', 15003)
        param.setdefault('prefix', '{}/{}'.format(self._log_path, 'tti'))
        self._log.debug(param)
        return param

    def _execute_tti_stream_cmd(self, cmd, except_str=None):
        out = self._executor.execute_command("{}\n".format(cmd.strip()))
        if except_str and except_str not in out:
            raise Exception('start {} fail, there is no [{}] in return.'.format(cmd, except_str))

    def _get_created_dat_file(self):
        out = self._executor.run('ls {}*.dat'.format(self._prefix))
        return self._extract_dat_files_from_output(out)

    def _extract_dat_files_from_output(self, out):
        dat_files = self._get_accurate_dat_file(out)
        if not len(dat_files):
            raise Exception('No Dat File was created.')
        else:
            return self._attach_log_path_to_output(dat_files)

    def _get_accurate_dat_file(self, out):
        files_list = out.split()
        target_dat = []
        for dat in files_list:
            ret = [dat for cell in self._cell_id if dat.count('_cell_{}.dat'.format(cell)) > 0]
            target_dat = target_dat + ret
        return target_dat

    def _get_node(self, lcr, table):
        cell_info_table = self._get_cell_info_table()
        lcr = lcr or self._get_first_local_cell_resource_id(cell_info_table)
        column = self._get_table_column(cell_info_table, table)
        return self._extract_node(cell_info_table, lcr, column)

    def _get_cell_info_table(self):
        tool_path = '{}/{}'.format(pkg_resources.resource_filename('ta_ttitrace', "resources"), 'getcellmapping')
        self._executor.run('sudo chmod u+x {}'.format(tool_path))
        cmd = 'sudo {} {} 15007'.format(tool_path, self._ip_addr)
        out = self._executor.run(cmd)
        cell_info_table = self._extract_table_from_output(out)
        return cell_info_table

    def _extract_table_from_output(self, out):
        try:
            return re.search(r'(lcr lnCel.*\n[\w\s.-]+)', out, re.MULTILINE).group(1)
        except Exception:
            raise Exception('Table not found.')

    def _get_first_local_cell_resource_id(self, cell_info_table):
        cells = cell_info_table.splitlines()
        return cells[1].split()[0]

    def _get_table_column(self, cell_info_table, table):
        cells = cell_info_table.splitlines()
        tables = cells[0].split()
        for index in range(0, len(tables)):
            if table == tables[index]:
                return index
        raise Exception("{} did not match any table name".format(table))

    def _extract_node(self, cell_info_table, lcr, node):
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[0] == lcr:
                return cell.split()[node][:10] if len(cell.split()[node]) >= 10 else cell.split()[node][:6]
        raise Exception('{} did not match any local cell resource'.format(lcr))

    def _validate_ouput_file_created(self, out):
        lines = out.splitlines()
        p = re.compile(r'Creating ASCII File (\S+)')
        for line in lines:
            m = p.match(line)
            if m:
                return m.group(1)
        return ''

    def _get_default_stream_path(self):
        base_path = pkg_resources.resource_filename(__name__, "resources")
        server_stream_path = '{}/{}'.format(base_path, 'cli_aatrace_utility_debian')
        client_stream_path = '{}/{}'.format(base_path, 'remote_execute_cli_debian')
        online_stream_path = '{}/{}'.format(base_path, 'onlineTtiStream_64')
        stream_path = {'server': server_stream_path,
                       'client': client_stream_path,
                       "online": online_stream_path}
        return stream_path

    def _get_default_tracer_path(self):
        tracer_name = 'tti_trace_parser_wmp-linux.exe'
        tracer_path = self._find_tracer_path(tracer_name, '/opt/TtiTracer')
        return tracer_path

    def _find_tracer_path(self, name, path):
        try:
            return self._executor.run('find {} -name {}'.format(path, name)).split()[0]
        except Exception:
            raise Exception('Default Ttitracer not found.')

    def _ensure_ttitracers_are_executable(self):
        if not isinstance(self._stream_path, dict):
            self._stream_path = self._separate_stream_tool(self._stream_path)
        for tool in self._stream_path:
            self._executor.run('sudo chmod u+x {}'.format(self._stream_path[tool]))
        self._executor.run('sudo chmod u+x {}'.format(self._tracer_path))

    def _create_dict(self, dict, value):
        expect_tools = {'server': 'cli_aatrace_utility_debian',
                        'client': 'remote_execute_cli_debian',
                        'online': 'onlineTtiStream'}
        for type, expect_tool in expect_tools.items():
            dict.setdefault(type, value) if expect_tool in value else None
        return dict

    def _separate_stream_tool(self, stream_path):
        stream_path_dict = {}
        self._log.debug('input tool is {}'.format(stream_path))
        tools = str(stream_path).split(',')
        for tool in tools:
            stream_path_dict = self._create_dict(stream_path_dict, tool)
        if len(stream_path_dict.keys()) != 3:
            self._log.info("!!! Input stream_path is incomplete, now use the default tools. !!!")
            stream_path_dict = self._get_default_stream_path()
        return stream_path_dict

    def _separate_core_id(self, core_id):
        core_id_pre_cell = []
        pre_core_id = core_id.split(',')
        for id in range(0, len(pre_core_id), 2):
            core_id_pre_cell.append('{},{}'.format(pre_core_id[id], pre_core_id[id + 1]))
        self._log.debug('separate core id as cell:{}'.format(core_id_pre_cell))
        return core_id_pre_cell


class Fsm4MixedFddTddTtiTrace(TtiTrace):

    def __init__(self, host_ip, ssh_username, ssh_password, ssh_prompt, ssh_port, stream_path,
                 tracer_path, ip_addr, timeout, log_path, sw_version, cells_sw_type):
        self._log = logging.getLogger(__name__)
        super(Fsm4MixedFddTddTtiTrace, self).__init__(host_ip, ssh_username, ssh_password, ssh_prompt, ssh_port,
                                                      stream_path, tracer_path, ip_addr, timeout, log_path, sw_version,
                                                      cells_sw_type)
        self._ip_addr = ip_addr
        self._started = False
        self._cell_id = []
        self._is_server_model = True
        self.cell_info_table = ''
        self._host_ip = host_ip
        self._ip_addr = ip_addr

    def start_tti_stream(self, core, param):
        """Start ttiStream with provided params
        """
        if self._started:
            raise Exception('Tti Stream already started.')
        if len(core.split(',')) < 2:
            raise Exception("Both DL and UL core are needed.")

        param = self._set_default_value(param)
        self._prefix = param['prefix']
        self._port = param['port']

        server_cmd = 'cd {};sudo {} -H r4 -s 1 -c defaultTraces=0 -c tracing_disabled=1 -p {} -M 0' \
            .format(self._log_path, self._stream_path['server'], param['port'])
        self._executor.write_to_shell('{}\n'.format(server_cmd))
        self._executor.read_until('node settings:')
        time.sleep(6)

        core_id_pre_cell = self._separate_core_id(core)
        for core_id in core_id_pre_cell:
            lncell = self._get_lncell_by_core(core_id)
            sw_type = self._get_sw_type_by_core(core_id)
            self._cell_id.append(lncell)

            client_cmd1 = 'sudo {} -m CLIAATRACE_MSG_ID_REGISTER_CELL_ID_PACKET_SCHEDULER_MAPPING -c "{} {}"'\
                          .format(self._stream_path['client'], lncell, core_id.replace(',', ' '))
            self._execute_tti_stream_cmd(client_cmd1, 'received msg ID:')

            client_cmd2 = 'sudo {} -m CLIAATRACE_MSG_ID_LTE2114_Q_B_TTI_TRACE_START -c "{} {}"'\
                          .format(self._stream_path['client'], '{}_{}'.format(param['prefix'], sw_type), lncell)
            self._execute_tti_stream_cmd(client_cmd2, 'START LTE211-Q-b streaming  OK')

        self._started = True

    def stop_tti_stream(self, lrc=None):
        """Stop running ttiStream
        """
        if not self._started:
            raise Exception('There is no started ttiStream')
        for cell in self._cell_id:
            stop_cmd = 'sudo {} -m CLIAATRACE_MSG_ID_LTE2114_Q_B_TTI_TRACE_STOP -c "{}"'\
                .format(self._stream_path['client'], cell)
            self._execute_tti_stream_cmd(stop_cmd)
        self._started = False
        out = self._get_created_dat_file()
        self._log_files.extend(out)
        self._cell_id = []
        return out

    def stop_tti_stream_and_convert_to_text(self, nb, ext='txt', lrc=None):
        """Stop running ttiStream and convert dat files to txt
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension
        :return list:                   List of successfully converted txt file
        """
        dat_files = self.stop_tti_stream()
        return list(filter(None, [self.convert_dat_to_text(source=file, destination=None, nb=nb, ext=ext) for file in dat_files]))

    def convert_dat_to_text(self, source, destination, nb, ext='txt'):
        """Converts source dat file to readable text file
        :param source string:           Input dat file name
        :param destination string:      Output txt file name
        :param nb bool:                 Use NB parsing flag
        :param ext string:              Output file extension, ignored when destination is given
        :return string:                 Output txt file or empty string if txt file not created
        """
        destination = destination or "{}.{}".format(source, ext)
        self._log.debug("Technology:{}".format(self._cells_sw_type))
        sw_type = self._cells_sw_type[source.split("_")[-1].split('.')[0]]
        if 'TDD' == sw_type:
            self._log.debug("TDD decode")
            return self._convert_tdd_dat(source, destination, nb, ext='txt')
        elif 'FDD' == sw_type:
            self._log.debug("FDD decode")
            return self._convert_fdd_dat(source, destination, nb, ext='txt')
        else:
            raise Exception("Don't analysis whether TDD or FDD. Can't select the decode tool.")

    def get_tti_dl_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:                TTI DL Node
        """
        return self._get_node(lcr, table='MACDLTTI')

    def get_tti_ul_node(self, lcr=None):
        """Get tti DL Node
        :param lcr string:      Local Cell Resource ID
        :return string:         TTI UL Node
        """
        return self._get_node(lcr, table='MACULTTI')

    def _get_lncell_by_core(self, core):
        input_core = core.split(',')
        input_core.sort()
        cell_info_table = self._get_cell_info_table()
        column = self._get_table_column(cell_info_table, table='MACDLTTI')
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[1].isdigit() and cell.split()[column] in input_core and cell.split()[1] not in self._cell_id:
                return cell.split()[1]
        else:
            raise Exception("The core is not for any cell.")

    def _get_sw_type_by_core(self, core):
        input_core = core.split(',')
        input_core.sort()
        cell_info_table = self._get_cell_info_table()
        core_column = self._get_table_column(cell_info_table, table='MACDLTTI')
        pool_type_column = self._get_table_column(cell_info_table, 'L2PoolType')
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[1].isdigit() and cell.split()[core_column] in input_core and\
                    cell.split()[1] not in self._cell_id:
                return re.findall(r'.*_(.*)_.*', cell.split()[pool_type_column])[0]
        else:
            raise Exception("The core is not for any cell.")

    def _set_default_value(self, param):
        param.setdefault('ip_addr', self._ip_addr)
        param.setdefault('port', 15003)
        param.setdefault('prefix', '{}/{}'.format(self._log_path, 'tti'))
        self._log.debug(param)
        return param

    def _execute_tti_stream_cmd(self, cmd, except_str=None):
        out = self._executor.execute_command("{}\n".format(cmd.strip()))
        if except_str and except_str not in out:
            raise Exception('start {} fail, there is no [{}] in return.'.format(cmd, except_str))

    def _get_created_dat_file(self):
        out = self._executor.run('ls {}*.dat'.format(self._prefix))
        return self._extract_dat_files_from_output(out)

    def _extract_dat_files_from_output(self, out):
        dat_files = self._get_accurate_dat_file(out)
        if not len(dat_files):
            raise Exception('No Dat File was created.')
        else:
            return self._attach_log_path_to_output(dat_files)

    def _get_accurate_dat_file(self, out):
        files_list = out.split()
        target_dat = []
        for dat in files_list:
            ret = [dat for cell in self._cell_id if dat.count('_cell_{}.dat'.format(cell)) > 0]
            target_dat = target_dat + ret
        return target_dat

    def _get_node(self, lcr, table):
        cell_info_table = self._get_cell_info_table()
        lcr = lcr or self._get_first_local_cell_resource_id(cell_info_table)
        column = self._get_table_column(cell_info_table, table)
        return self._extract_node(cell_info_table, lcr, column)

    def _get_cell_info_table(self):
        if self.cell_info_table == '':
            tool_path = '{}/{}'.format(pkg_resources.resource_filename('ta_ttitrace', "resources"), 'getcellmapping')
            self._executor.run('sudo chmod u+x {}'.format(tool_path))
            cmd = 'sudo {} {} 15007'.format(tool_path, self._ip_addr)
            out = self._executor.run(cmd)
            cell_info_table = self._extract_table_from_output(out)
            return cell_info_table
        else:
            cell_mapping_info_table = self.cell_info_table
        return cell_mapping_info_table

    def _extract_table_from_output(self, out):
        try:
            return re.search(r'(lcr lnCel.*\n[\w\s.-]+)', out, re.MULTILINE).group(1)
        except Exception:
            raise Exception('Table not found.')

    def _get_first_local_cell_resource_id(self, cell_info_table):
        cells = cell_info_table.splitlines()
        return cells[1].split()[0]

    def _get_table_column(self, cell_info_table, table):
        cells = cell_info_table.splitlines()
        tables = cells[0].split()
        for index in range(0, len(tables)):
            if table == tables[index]:
                return index
        raise Exception("{} did not match any table name".format(table))

    def _extract_node(self, cell_info_table, lcr, node):
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[0] == lcr:
                return cell.split()[node][:10] if len(cell.split()[node]) >= 10 else cell.split()[node][:6]
        raise Exception('{} did not match any local cell resource'.format(lcr))

    def _validate_ouput_file_created(self, out):
        lines = out.splitlines()
        p = re.compile(r'Creating ASCII File (\S+)')
        for line in lines:
            m = p.match(line)
            if m:
                return m.group(1)
        return ''

    def _get_default_stream_path(self):
        base_path = pkg_resources.resource_filename(__name__, "resources")
        server_stream_path = '{}/{}'.format(base_path, 'cli_aatrace_utility_debian')
        client_stream_path = '{}/{}'.format(base_path, 'remote_execute_cli_debian')
        online_stream_path = '{}/{}'.format(base_path, 'onlineTtiStream_64')
        stream_path = {'server': server_stream_path,
                       'client': client_stream_path,
                       "online": online_stream_path}
        return stream_path

    def _get_default_tracer_path(self):
        fdd_tracer_name = 'tti_trace_parser_wmp-linux.exe'
        fdd_tracer_path = self._find_tracer_path(fdd_tracer_name, '/opt/TtiTracer')
        tdd_tracer_name = 'DevC_tti_trace_parser_64'
        tdd_tracer_path = self._find_tracer_path(tdd_tracer_name, '/opt/TtiTracer')
        tracer_path = {'TDD': tdd_tracer_path, 'FDD': fdd_tracer_path}
        return tracer_path

    def _get_default_tdd_tracer_path(self):
        tracer_name = 'DevC_tti_trace_parser_64'
        tracer_path = self._find_tracer_path(tracer_name, '/opt/TtiTracer')
        return tracer_path

    def _find_tracer_path(self, name, path):
        try:
            return self._executor.run('find {} -name {}'.format(path, name)).split()[0]
        except Exception:
            raise Exception('Default Ttitracer not found.')

    def _ensure_ttitracers_are_executable(self):
        if not isinstance(self._stream_path, dict):
            self._stream_path = self._separate_stream_tool(self._stream_path)
        for tool in self._stream_path:
            self._executor.run('sudo chmod u+x {}'.format(self._stream_path[tool]))
        if not isinstance(self._tracer_path, dict):
            self._tracer_path = self._separate_tracer_tool(self._tracer_path)
        for tool in self._tracer_path:
            self._executor.run('sudo chmod u+x {}'.format(self._tracer_path[tool]))

    def _create_stream_dict(self, dict, value):
        expect_tools = {'server': 'cli_aatrace_utility_debian',
                        'client': 'remote_execute_cli_debian',
                        'online': 'onlineTtiStream'}
        for type, expect_tool in expect_tools.items():
            dict.setdefault(type, value) if expect_tool in value else None
        return dict

    def _create_tracer_dict(self, dict, value):
        expect_tools = {'FDD': 'tti_trace_parser_wmp-linux.exe',
                        'TDD': 'DevC_tti_trace_parser_64'}
        for type, expect_tool in expect_tools.items():
            dict.setdefault(type, value) if expect_tool in value else None
        return dict

    def _separate_stream_tool(self, stream_path):
        stream_path_dict = {}
        self._log.debug('input tool is {}'.format(stream_path))
        tools = str(stream_path).split(',')
        for tool in tools:
            stream_path_dict = self._create_stream_dict(stream_path_dict, tool)
        if len(stream_path_dict.keys()) != 3:
            self._log.info("!!! Input stream_path is incomplete, now use the default tools. !!!")
            stream_path_dict = self._get_default_stream_path()
        return stream_path_dict

    def _separate_tracer_tool(self, tracer_path):
        tracer_path_dic = {}
        self._log.debug('input tool is {}'.format(tracer_path))
        tools = str(tracer_path).split(',')
        for tool in tools:
            tracer_path_dic = self._create_tracer_dict(tracer_path_dic, tool)
        return tracer_path_dic

    def _separate_core_id(self, core_id):
        core_id_pre_cell = []
        pre_core_id = core_id.split(',')
        for id in range(0, len(pre_core_id), 2):
            core_id_pre_cell.append('{},{}'.format(pre_core_id[id], pre_core_id[id + 1]))
        self._log.debug('separate core id as cell:{}'.format(core_id_pre_cell))
        return core_id_pre_cell

    def _convert_tdd_dat(self, source, destination, nb, ext='txt'):
        cmd = 'cd {}; {} {} {}'.format(self._log_path, self._tracer_path['TDD'], source, destination)
        out = self._executor.run(cmd.strip())
        if re.search('parse complete.', out):
            output_file = self._attach_log_path_if_not_absolute(destination)
            self._log_files.append(output_file)
            return output_file
        return ''

    def _convert_fdd_dat(self, source, destination, nb, ext='txt'):
        cmd = 'cd {};sudo {} --decode {} --output {} {}'.format(self._log_path, self._tracer_path['FDD'],
                                                                source, destination, '-nb' if nb else '')
        out = self._executor.run(cmd.strip())
        output = self._validate_ouput_file_created(out)
        if output:
            self._log_files.append(output)
        return output
